/// The catalog entries of a colorset (ARCHITECTURE §9.8): Any, Dark, High Contrast, Dark + High Contrast and the
/// `watch` idiom entry, which carries the dark value (watchOS keeps no contrast entries).
public struct DSColorAppearances: Hashable, Sendable {
    public let any: DSRGBA
    public let dark: DSRGBA
    public let highContrast: DSRGBA
    public let darkHighContrast: DSRGBA
    public let watch: DSRGBA

    public init(any: DSRGBA, dark: DSRGBA, highContrast: DSRGBA, darkHighContrast: DSRGBA, watch: DSRGBA) {
        self.any = any
        self.dark = dark
        self.highContrast = highContrast
        self.darkHighContrast = darkHighContrast
        self.watch = watch
    }
}

/// The colors of one brand (ADR-0020 §7), reached as `tokens.color`: one member per `sys.color` token, each a
/// catalog color in the brand's namespace folder; a member with a reduced-transparency colorset picks it while
/// `transparency` is reduced.
public struct DSColor: Hashable, Sendable {
    public let brand: DSBrand
    public let transparency: DSTransparency

    public init(brand: DSBrand, transparency: DSTransparency) {
        self.brand = brand
        self.transparency = transparency
    }

    /// marks: dots, chart 'now', peak ticks, delta glyph fill; 2.3:1 on white, so a mark always sits with its value, sign or label, and a mark that alone carries meaning uses accent.700 (4.8:1; visual-dna B3)
    public var accent: Color { DSColorToken.accent.color(brand) }

    public var accentGlow: Color { DSColorToken.accentGlow.color(brand) }

    public var accentPressed: Color { DSColorToken.accentPressed.color(brand) }

    public var accentSubtle: Color { DSColorToken.accentSubtle.color(brand) }

    /// the one attention tile; content is ink
    public var bgFillAccent: Color { DSColorToken.bgFillAccent.color(brand) }

    /// accent surface with white text (4.8:1)
    public var bgFillAccentStrong: Color { DSColorToken.bgFillAccentStrong.color(brand) }

    /// badge under white 11 px Medium (4.5:1)
    public var bgFillCritical: Color { DSColorToken.bgFillCritical.color(brand) }

    /// primary pill, active tab, solid action circle
    public var bgFillInverse: Color { DSColorToken.bgFillInverse.color(brand) }

    public var bgFillNeutralSubtle: Color { DSColorToken.bgFillNeutralSubtle.color(brand) }

    /// never flat pure grey; optional warm mesh toward #F3F0EB and blooms at 25-35%
    public var bgPage: Color { DSColorToken.bgPage.color(brand) }

    /// card: no border, no shadow (optional ambient 5%)
    public var bgSurface: Color { DSColorToken.bgSurface.color(brand) }

    /// filled control, dock tray (= #F0F1F1 on white)
    public var bgSurfaceNested: Color { DSColorToken.bgSurfaceNested.color(brand) }

    public var bgSurfaceOverlay: Color { DSColorToken.bgSurfaceOverlay.color(brand) }

    /// puffy chip / round button on the page, plus inset top highlight and elevation.1
    public var bgSurfaceRaised: Color { DSColorToken.bgSurfaceRaised.color(brand) }

    /// tinted focus card (= #FEF2E9 on white)
    public var bgTintAccent: Color { DSColorToken.bgTintAccent.color(brand) }

    public var bgTintCritical: Color { DSColorToken.bgTintCritical.color(brand) }

    public var bgTintInfo: Color { DSColorToken.bgTintInfo.color(brand) }

    public var bgTintSuccess: Color { DSColorToken.bgTintSuccess.color(brand) }

    public var bgTintWarning: Color { DSColorToken.bgTintWarning.color(brand) }

    /// control edges that must pass 3:1
    public var borderBoundary: Color { DSColorToken.borderBoundary.color(brand) }

    public var borderFocus: Color { DSColorToken.borderFocus.color(brand) }

    /// inputs, table rows, chip strokes
    public var borderHairline: Color { DSColorToken.borderHairline.color(brand) }

    /// outline controls such as the ghost button; ink 45% keeps 3:1 on surface and page (visual-dna B1)
    public var borderStrong: Color { DSColorToken.borderStrong.color(brand) }

    /// reference #B7B7B9 failed at 1.7:1
    public var chartAxis: Color { DSColorToken.chartAxis.color(brand) }

    public var chartBand: Color { DSColorToken.chartBand.color(brand) }

    /// comparison line; ink 45% keeps 3:1 on the plot, the boundary tier of chart lines that carry meaning (ADR-0011; ink 30% was 2.0:1, critic G-14)
    public var chartComparison: Color { DSColorToken.chartComparison.color(brand) }

    public var chartComparison2: Color { DSColorToken.chartComparison2.color(brand) }

    /// sparkline ghost bars
    public var chartGhost: Color { DSColorToken.chartGhost.color(brand) }

    public var chartGrid: Color { DSColorToken.chartGrid.color(brand) }

    /// the now marker; 2.3:1 on white, so it always carries its label or value (visual-dna B3)
    public var chartNow: Color { DSColorToken.chartNow.color(brand) }

    /// charts never sit on raw glass
    public var chartPlot: Color { DSColorToken.chartPlot.color(brand) }

    public var chartSeries1: Color { DSColorToken.chartSeries1.color(brand) }

    public var chartSeries2: Color { DSColorToken.chartSeries2.color(brand) }

    public var chartSeries3: Color { DSColorToken.chartSeries3.color(brand) }

    public var chartSeries4: Color { DSColorToken.chartSeries4.color(brand) }

    public var chartSeries5: Color { DSColorToken.chartSeries5.color(brand) }

    public var chartSeries6: Color { DSColorToken.chartSeries6.color(brand) }

    /// the mandatory target line (ADR-0007 rule 2); ink 45% keeps 3:1 on the plot, the boundary tier (ADR-0011; ink 30% was 2.0:1, critic G-14)
    public var chartTarget: Color { DSColorToken.chartTarget.color(brand) }

    /// marks only, never text; 2.3:1 on white, so always paired with a value, sign or label (visual-dna B3)
    public var iconAccent: Color { DSColorToken.iconAccent.color(brand) }

    public var iconPrimary: Color { DSColorToken.iconPrimary.color(brand) }

    public var iconSecondary: Color { DSColorToken.iconSecondary.color(brand) }

    public var iconStatusCritical: Color { DSColorToken.iconStatusCritical.color(brand) }

    public var iconStatusInfo: Color { DSColorToken.iconStatusInfo.color(brand) }

    public var iconStatusSuccess: Color { DSColorToken.iconStatusSuccess.color(brand) }

    public var iconStatusWarning: Color { DSColorToken.iconStatusWarning.color(brand) }

    /// 5.7:1 on page; the light accent is text-safe only at step 800
    public var textAccent: Color { DSColorToken.textAccent.color(brand) }

    public var textCritical: Color { DSColorToken.textCritical.color(brand) }

    /// 3.4:1 on page: trailing digits and units at >= 24 px only
    public var textDimmed: Color { DSColorToken.textDimmed.color(brand) }

    public var textInfo: Color { DSColorToken.textInfo.color(brand) }

    /// ink on accent-300 = 12.0:1
    public var textOnAccent: Color { DSColorToken.textOnAccent.color(brand) }

    public var textOnAccentStrong: Color { DSColorToken.textOnAccentStrong.color(brand) }

    public var textOnBadge: Color { DSColorToken.textOnBadge.color(brand) }

    /// white on dark glass; light glass uses on-glass-light (ADR-0022)
    public var textOnGlass: Color { DSColorToken.textOnGlass.color(brand) }

    /// ink on light glass in the light scheme; hierarchy by size, never by alpha (ADR-0022 §3)
    public var textOnGlassLight: Color { DSColorToken.textOnGlassLight.color(brand) }

    /// secondary tone on dark glass (the glass material) only; chips and cells use on-glass (ADR-0022 §3)
    public var textOnGlassSecondary: Color { DSColorToken.textOnGlassSecondary.color(brand) }

    /// tertiary and dimmed tones on dark glass (the glass material) only (ADR-0022 §3)
    public var textOnGlassTertiary: Color { DSColorToken.textOnGlassTertiary.color(brand) }

    public var textOnInverse: Color { DSColorToken.textOnInverse.color(brand) }

    /// every vivid gradient passes ADR-0022 V1/V2
    public var textOnVivid: Color { DSColorToken.textOnVivid.color(brand) }

    /// 17.2:1 on page
    public var textPrimary: Color { DSColorToken.textPrimary.color(brand) }

    /// 5.6:1 page / 6.3:1 card (reference #8E8E8E failed at 2.4:1)
    public var textSecondary: Color { DSColorToken.textSecondary.color(brand) }

    public var textSuccess: Color { DSColorToken.textSuccess.color(brand) }

    /// resolves to the secondary step so 12 px captions pass AA; the DNA's #7E838F is kept as text.dimmed for >= 24 px
    public var textTertiary: Color { DSColorToken.textTertiary.color(brand) }

    public var textWarning: Color { DSColorToken.textWarning.color(brand) }
}
